import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] b = new long[(int) m];
        for (int i = 0; i < b.length; i++) b[i] = Long.parseLong(next());

        Set<Long> first = new HashSet<>();
        for (int i = 0; i < n; i++) first.add(a[i]);
        TreeSet<Long> common = new TreeSet<>();
        for (int i = 0; i < m; i++) {
            if (first.contains(b[i])) common.add(b[i]);
        }
        StringBuilder sb = new StringBuilder();
        for (long v : common) sb.append(v).append(" ");
        System.out.println(common.size());
        System.out.println(sb.toString().trim());
    }
}
